<?php
require_once __DIR__.'/../includes/member.php'; $user=require_login(); if($user['role']==='admin') redirect('admin/dashboard.php');
$activeLoans=rows('SELECT br.*,b.title,b.book_id FROM borrowings br JOIN books b ON b.id=br.book_id WHERE br.user_id=? AND br.status IN ("active","overdue","pickup_pending","in_transit","awaiting_payment") ORDER BY br.due_date ASC',[$user['id']]);
$overdueCount=one('SELECT COUNT(*) as count FROM borrowings WHERE user_id=? AND status="overdue"',[$user['id']])['count']??0;
$student=one('SELECT * FROM users WHERE id=?',[$user['id']]);
$unpaidFines=rows('SELECT f.*,br.borrowed_at,b.title FROM fines f JOIN borrowings br ON br.id=f.borrowing_id JOIN books b ON b.id=br.book_id WHERE f.user_id=? AND f.status="unpaid"',[$user['id']]);
$totalUnpaidFines=array_sum(array_column($unpaidFines,'amount'));
member_start('Dashboard Siswa',$user,'dashboard.php');
?>
<section class="member-section" id="profile"><div class="member-section-heading"><div><span class="member-kicker">DATA SISWA SMA GLITZ</span><h1>Selamat datang, <?=e($student['name']??$user['name'])?></h1></div></div><div class="member-identity"><span class="profile-avatar"><?php if(!empty($student['photo_path'])):?><img src="<?=e(url($student['photo_path']))?>" alt="Foto <?=e($student['name'])?>"><?php else:?><?=e(strtoupper(substr($student['name']??$user['name'],0,1)))?><?php endif;?></span><div><b><?=e($student['name']??$user['name'])?></b><p>NIS: <strong><?=e($student['nis']??$student['member_id'])?></strong> · Kelas: <span class="badge" style="background:#0284c720;color:#0284c7;"><?=e($student['kelas']??'-')?></span></p><p style="font-size:12px;color:#64748b;margin-top:2px;"><?=e($student['address']??'Semarang')?></p></div><div class="member-barcode" aria-label="NIS <?=e($student['nis']??$student['member_id'])?>"><span></span><small><?=e($student['nis']??$student['member_id'])?></small></div></div></section>
<section class="member-section"><div class="member-section-heading"><div><span class="member-kicker">INFORMASI SEKOLAH</span><h2>Pengumuman Perpustakaan SMA GLITZ</h2></div></div><article class="notice member-notice-card"><b>Layanan Peminjaman Otomatis Siswa</b><p>Siswa SMA GLITZ dapat langsung meminjam buku melalui katalog tanpa perlu menginput alamat manual. Seluruh data identitas siswa otomatis terverifikasi sistem perpustakaan.</p></article><article class="notice member-notice-card"><b>Durasi Peminjaman</b><p>Masa peminjaman buku standar adalah 7 hari. Harap mengembalikan buku tepat waktu agar teman-teman lainnya dapat membaca.</p></article></section>
<section class="member-section"><div class="member-section-heading"><div><span class="member-kicker">STATUS PEMINJAMAN</span><h2>Peminjaman Aktif</h2></div><a class="member-see-all" href="<?=e(url('member/peminjaman.php'))?>">Lihat semua →</a></div><?php if($activeLoans):?><div class="loan-summary"><?php $nearestDue=null;foreach($activeLoans as $loan){if($loan['status']==='active'||$loan['status']==='overdue'){if($nearestDue===null||strtotime($loan['due_date'])<strtotime($nearestDue)){$nearestDue=$loan['due_date'];}}}?><p><strong><?=count($activeLoans)?></strong> buku sedang dipinjam</p><?php if($nearestDue):?><?php $daysUntilDue=(int)ceil((strtotime($nearestDue)-time())/86400);?><?php if($daysUntilDue>=0):?><p>Deadline terdekat: <strong><?=date_id($nearestDue,true)?></strong> (<?= $daysUntilDue ?> hari lagi)</p><?php else:?><p class="overdue-alert">Terlambat: <strong><?=abs($daysUntilDue)?> hari</strong></p><?php endif;?><?php endif;?><?php if($overdueCount>0):?><p class="overdue-alert"><strong><?= $overdueCount ?></strong> buku terlambat dikembalikan</p><?php endif;?></div><?php else:?><p>Belum ada peminjaman aktif.</p><?php endif;?></section>
<?php if($unpaidFines):?><section class="member-section"><div class="member-section-heading"><div><span class="member-kicker">DENDA</span><h2>Denda Belum Dibayar</h2></div><a class="member-see-all" href="<?=e(url('member/denda.php'))?>">Bayar sekarang →</a></div><div class="fine-summary"><p><strong><?=count($unpaidFines)?></strong> denda belum dibayar</p><p>Total: <strong>Rp <?=number_format($totalUnpaidFines,0,',','.')?></strong></p></div></section><?php endif;?>
<?php member_end(); ?>
